// Space.World: se mueve en el sistema de coordenadas GLOBAL
// Vector3.forward siempre apunta hacia Z+ del mundo
transform.Translate(Vector3.forward * speed * Time.deltaTime, Space.World);

// Space.Self (por defecto): se mueve en el sistema de coordenadas LOCAL
// El objeto se mueve en la dirección a la que ESTÁ MIRANDO
transform.Translate(Vector3.forward * speed * Time.deltaTime, Space.Self);
// Equivalente a:
transform.Translate(Vector3.forward * speed * Time.deltaTime); // Space.Self es el default

// Para mover en la dirección de mirada con Rigidbody:
rb.MovePosition(rb.position + transform.forward * speed * Time.fixedDeltaTime);

public class PlayerMovement : MonoBehaviour
{
    CharacterController cc;
    public float speed = 5f;
    public float gravity = -9.81f;
    private Vector3 velocity;

    void Awake() { cc = GetComponent<CharacterController>(); }

    void Update()
    {
        // Input del jugador
        float h = Input.GetAxis("Horizontal");
        float v = Input.GetAxis("Vertical");
        Vector3 move = transform.right * h + transform.forward * v;

        // Aplicar gravedad manual (CharacterController no tiene Rigidbody)
        velocity.y += gravity * Time.deltaTime;

        // Move combina el movimiento horizontal y la gravedad
        cc.Move((move * speed + velocity) * Time.deltaTime);
    }
}

